import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT_DIRECTORY = resolve(
  dirname(fileURLToPath(import.meta.url)),
  '..',
)
const SOURCE_FILE = resolve(
  ROOT_DIRECTORY,
  'config/owned-experiments.json',
)
const GENERATED_HEADER =
  '// Generated by scripts/generate-owned-experiment-registries.mjs. Do not edit.\n'
const SUPPORTED_INTENTS = [
  'visualize',
  'explain',
  'compare',
  'find-experiment',
]

function unique(values) {
  return [...new Set(values)]
}

function normalizedIdentifier(value) {
  return value.replaceAll('-', ' ')
}

function validateExperiments(experiments) {
  if (!Array.isArray(experiments) || experiments.length !== 18) {
    throw new Error('Owned experiment catalog must contain exactly 18 entries.')
  }

  const ids = new Set()
  for (const experiment of experiments) {
    const requiredFields = [
      'id',
      'title',
      'path',
      'knowledgePointId',
      'description',
      'topics',
      'ownership',
    ]
    if (
      !experiment ||
      requiredFields.some((field) => !(field in experiment)) ||
      !Array.isArray(experiment.topics)
    ) {
      throw new Error('Each owned experiment must include every catalog field.')
    }
    if (ids.has(experiment.id)) {
      throw new Error(`Duplicate owned experiment ID: ${experiment.id}`)
    }
    if (experiment.path !== `/demo/${experiment.id}`) {
      throw new Error(`Invalid owned experiment path: ${experiment.path}`)
    }
    if (experiment.ownership !== 'self-developed') {
      throw new Error(`Invalid ownership for ${experiment.id}.`)
    }
    ids.add(experiment.id)
  }
}

function renderClientCatalog(experiments) {
  return `${GENERATED_HEADER}
export interface OwnedExperimentCatalogEntry {
  id: string
  title: string
  path: string
  knowledgePointId: string
  description: string
  topics: readonly string[]
  ownership: 'self-developed'
}

export const OWNED_EXPERIMENT_CATALOG = ${JSON.stringify(experiments, null, 2)} as const satisfies readonly OwnedExperimentCatalogEntry[]

export type OwnedExperimentId = typeof OWNED_EXPERIMENT_CATALOG[number]['id']
`
}

function routeMetadata(experiment) {
  return {
    semanticEnabled: true,
    aliases: unique([
      experiment.title,
      experiment.id,
      normalizedIdentifier(experiment.id),
      experiment.knowledgePointId,
      normalizedIdentifier(experiment.knowledgePointId),
    ]),
    strongPhrases: [experiment.description],
    keywords: unique([
      ...experiment.topics,
      normalizedIdentifier(experiment.knowledgePointId),
    ]),
    supportedIntents: SUPPORTED_INTENTS,
  }
}

function renderServerRegistry(experiments) {
  const registry = experiments.map((experiment) => ({
    ...experiment,
    ...routeMetadata(experiment),
  }))

  return `${GENERATED_HEADER}
import type { RoutableMathIntent } from './experimentRegistry.js'

export interface OwnedExperimentRouteDefinition {
  id: string
  title: string
  path: string
  knowledgePointId: string
  description: string
  topics: readonly string[]
  ownership: 'self-developed'
  semanticEnabled: boolean
  aliases: readonly string[]
  strongPhrases: readonly string[]
  keywords: readonly string[]
  supportedIntents: readonly RoutableMathIntent[]
}

export const OWNED_EXPERIMENT_REGISTRY = ${JSON.stringify(registry, null, 2)} as const satisfies readonly OwnedExperimentRouteDefinition[]
`
}

const experiments = JSON.parse(await readFile(SOURCE_FILE, 'utf8'))
validateExperiments(experiments)

const sortedExperiments = [...experiments].sort((left, right) =>
  left.id.localeCompare(right.id),
)
const generatedFiles = new Map([
  [
    resolve(ROOT_DIRECTORY, 'client/src/owned-experiments/catalog.generated.ts'),
    renderClientCatalog(sortedExperiments),
  ],
  [
    resolve(ROOT_DIRECTORY, 'server/src/agent/ownedExperimentRegistry.generated.ts'),
    renderServerRegistry(sortedExperiments),
  ],
])

const checkOnly = process.argv.includes('--check')
for (const [filePath, content] of generatedFiles) {
  let currentContent = null
  try {
    currentContent = await readFile(filePath, 'utf8')
  } catch (error) {
    if (error.code !== 'ENOENT') {
      throw error
    }
  }

  if (checkOnly) {
    if (currentContent !== content) {
      throw new Error(`Owned experiment registry is out of date: ${filePath}`)
    }
    continue
  }

  await mkdir(dirname(filePath), { recursive: true })
  await writeFile(filePath, content)
}

console.log(
  checkOnly
    ? 'Owned experiment registries are up to date.'
    : 'Owned experiment registries generated.',
)
